// Two bars: share of called patients who came back within 30 days, by when the call was made.
const frame = (context.panel.data.series || []).find((s) => s.refId === 'A') || (context.panel.data.series || [])[0];
function col(n) { const f = frame && frame.fields.find((x) => x.name === n); if (!f) { return []; } return Array.from(f.values && f.values.buffer ? f.values.buffer : f.values); }
const one = (n) => { const v = col(n)[0]; return v === null || v === undefined || v === '' ? null : Number(v); };
const C = chartColors;
const rv = context.grafana && context.grafana.replaceVariables;
const allowed = !rv || rv('${isAllowed}') === '1';
const centre = (text) => ({ graphic: allowed ? [{ type: 'text', left: 'center', top: 'middle', style: { text: text, fontSize: 14, fill: C.muted } }] : [] });
if (!col('return_known_n').length) { return centre('No data for this place.'); }
const K = one('return_known_n') || 0, R = one('returned_n') || 0, pe = one('returned_early_pct'), pl = one('returned_later_pct');
const wait = one('return_not_yet_known_n') || 0;
const days = one('early_days'), back = one('return_days');
if (!K) { return centre('No calls old enough to check yet.'); }
// report_calling gives the two shares (one decimal) and their totals. The counts behind each share are
// the whole numbers that give back both shares exactly; the closest to the algebraic split wins.
const p1 = (x, d) => (d ? Math.round(1000 * x / d) / 10 : null);
const same = (a, b) => (a === null || b === null ? a === b : Math.abs(a - b) < 0.051);
const guess = pe !== null && pl !== null && pe !== pl ? (R - pl / 100 * K) / ((pe - pl) / 100) : pe === null ? 0 : K;
let split = null;
for (let ek = 0; ek <= K; ek++) {
  const lk = K - ek;
  const base = pe === null ? 0 : Math.round(pe * ek / 100);
  [base - 1, base, base + 1].forEach((re) => {
    const rl = R - re;
    if (re < 0 || re > ek || rl < 0 || rl > lk) { return; }
    if (!same(p1(re, ek), pe) || !same(p1(rl, lk), pl)) { return; }
    if (!split || Math.abs(ek - guess) < Math.abs(split[0] - guess)) { split = [ek, re, lk, rl]; }
  });
}
const pctTxt = (v) => (v === null ? '—' : (Math.abs(v) < 10 ? v.toFixed(1) : String(Math.round(v))) + '%');
const names = ['Called within ' + fmt(days) + ' days', 'Called later'];
const share = [pe, pl];
const nOf = split ? [[split[1], split[0]], [split[3], split[2]]] : [null, null];
const label = (k) => pctTxt(share[k]) + (nOf[k] ? ' · ' + fmt(nOf[k][0]) + ' of ' + fmt(nOf[k][1]) : '');
const line = (k) => (share[k] === null ? 'No calls in this group'
  : nOf[k] ? fmt(nOf[k][0]) + ' of ' + fmt(nOf[k][1]) + ' came back (' + pctTxt(share[k]) + ')' : pctTxt(share[k]) + ' came back');
return {
  animation: false,
  grid: { left: 8, right: 120, top: 8, bottom: wait ? 40 : 16, containLabel: true },
  tooltip: tip((k) => [line(k)], (k) => names[k], { axisPointer: { type: 'shadow', shadowStyle: { color: 'rgba(110,127,141,0.12)' } } }),
  yAxis: { type: 'category', inverse: true, data: names, axisTick: { show: false },
    axisLabel: { color: C.text, fontSize: 13 }, axisLine: { lineStyle: { color: C.axisLine } } },
  xAxis: { type: 'value', min: 0, max: 100, interval: 25, axisLabel: { color: C.axis, fontSize: 11, formatter: (v) => v + '%' },
    splitLine: { lineStyle: { color: C.grid } } },
  series: [{
    type: 'bar', name: 'Came back', barWidth: '46%',
    data: share.map((v, k) => ({ value: v === null ? 0 : v, itemStyle: { color: k ? C.step[1] : C.step[4], borderRadius: [0, 2, 2, 0] } })),
    label: { show: true, position: 'right', color: C.text, fontSize: 12, formatter: (p) => label(p.dataIndex) }
  }],
  graphic: wait ? [{ type: 'text', left: 8, bottom: 8, style: { text: fmt(wait) + ' more calls are too recent to check. They need ' + fmt(back) + ' days.', fontSize: 12, fill: C.muted } }] : []
};

