// Facility table: Facility, Overdue with a phone, Called, Calls made early, Came back, Why look here.
const root = rpt.mount('.rpt-cal-table');
if (!root) { return; }
const { esc, fmt, num, yes, pct } = rpt;
const low = (v, at) => num(v) !== null && num(at) !== null && num(v) < num(at);
// Flags: two from report_calling, one from the new-patient phone flag (EP-12). At most two pills.
const hits = (r) => [
  low(r.called_pct, r.called_below_pct) && !yes(r.too_few) ? ['Few called', 'Only ' + pct(r.called_pct) + ' of ' + fmt(r.overdue_with_phone_n) + ' overdue patients with a phone were called.'] : null,
  low(r.early_pct, r.early_below_pct) && !yes(r.too_few) ? ['Mostly late calls', 'Only ' + pct(r.early_pct) + ' of ' + fmt(r.called_n) + ' calls were within ' + fmt(r.early_days) + ' days.'] : null,
  yes(r.phone_flag) ? ['Few phone numbers', 'Only ' + pct(r.new_usable_phone_pct) + ' of ' + fmt(r.new_patients_n) + ' new patients have a usable phone number.'] : null
].filter(Boolean).slice(0, 2);
const rows = rpt.rows('A').map((r) => Object.assign({}, r, { flag: yes(r.flag) || yes(r.phone_flag) }));
const share = (p, n, d) => (num(p) === null ? '—' : pct(p) + '<div class="rpt-cnt">' + fmt(n) + ' of ' + fmt(d) + '</div>');
rptTable(root, {
  report: 'calling',
  rows: rows,
  caption: 'Overdue patients with a phone, calls and returns, by facility. Flagged facilities come first.',
  columns: [
    { label: 'Overdue with a phone', num: true, value: (r) => num(r.overdue_with_phone_n), cell: (r) => fmt(r.overdue_with_phone_n) },
    { label: 'Called', num: true, guard: true, value: (r) => num(r.called_pct), cell: (r) => share(r.called_pct, r.called_n, r.overdue_with_phone_n) },
    { label: 'Calls made early', num: true, guard: true, value: (r) => num(r.early_pct), cell: (r) => share(r.early_pct, r.early_n, r.called_n) },
    { label: 'Came back', num: true, guard: true, value: (r) => num(r.returned_pct), cell: (r) => share(r.returned_pct, r.returned_n, r.return_known_n),
      title: (r) => 'Visited within ' + fmt(r.return_days) + ' days of the call' }
  ],
  flagNames: (r) => hits(r).map((h) => h[0]),
  reason: (r) => hits(r).map((h) => h[1]).join(' '),
  guardName: 'Too few patients',
  guardReason: (r) => rpt.needAtLeast(r.min_overdue_phone, r.overdue_with_phone_n),
  alsoOn: ['adherence', 'titration', 'fudging', 'statins'],
  size: (r) => num(r.overdue_with_phone_n)
});

