// New patients: did not come back within 90 days, usable phone, and the cohort they come from.
const root = rpt.mount('.rpt-cal-new');
if (!root) { return; }
const { esc, fmt, num, yes, pct } = rpt;
const r = rpt.rows('A')[0];
const col = (big, cls, color, label, line) => '<div>'
  + '<div class="rpt-big' + (cls ? ' ' + cls : '') + '"' + (color ? ' style="color:' + color + '"' : '') + '>' + esc(big) + '</div>'
  + '<div class="rpt-label">' + esc(label) + '</div><div class="rpt-line">' + esc(line) + '</div></div>';
if (!r) {
  root.innerHTML = '<div class="rpt-strip3">' + col('—', '', '', 'Did not come back', rpt.NO_DATA) + col('—', '', '', 'Usable phone number', rpt.NO_DATA)
    + col('—', '', '', 'New patients', rpt.NO_DATA) + '</div>';
  return;
}
const N = num(r.new_patients_n) || 0, back = num(r.new_returned_n) || 0, ph = num(r.new_usable_phone_n) || 0;
// Cohort (CR-6): first visit 90 to 179 days before the window end.
const end = rpt.toDate(r.window_end);
const shift = (d) => (end ? rpt.day(new Date(end.getTime() - d * 86400000).toISOString().slice(0, 10)) : '');
const cohort = 'first visit ' + shift(179) + ' to ' + shift(90);
if (yes(r.too_few) || !N) {
  const few = N ? col('Too few patients', 'rpt-few', '', 'Did not come back', rpt.needAtLeast(r.min_patients, N)) : col('—', '', '', 'Did not come back', rpt.NO_DATA);
  root.innerHTML = '<div class="rpt-strip3">' + few + col('—', '', '', 'Usable phone number', N ? rpt.needAtLeast(r.min_patients, N) : rpt.NO_DATA)
    + col(fmt(N), '', 'var(--text-primary)', 'New patients', cohort) + '</div>';
  return;
}
const lowPhone = yes(r.flag);
root.innerHTML = '<div class="rpt-strip3">'
  + col(pct(r.new_loss_pct), '', 'var(--no-visit)', 'Did not come back', fmt(N - back) + ' of ' + fmt(N) + ' new patients had no visit within 90 days')
  + col(pct(r.new_usable_phone_pct), '', lowPhone ? 'var(--flag-bar)' : 'var(--text-primary)', 'Usable phone number',
    fmt(ph) + ' of ' + fmt(N) + ' new patients have one.' + (num(r.phone_below_pct) !== null ? ' Under ' + pct(r.phone_below_pct) + ' is flagged.' : ''))
  + col(fmt(N), '', 'var(--text-primary)', 'New patients', cohort) + '</div>';
